assignments.value:
={{ (() => {
  const p = $('Limpiar payload').first().json;
  const dec = $('Llamar Validador').isExecuted
    ? ($('Llamar Validador').first().json.data?.decision || 'ESCALADO')
    : $('Router').first().json.output.categoria;
  const alerta = ['ESCALADO', 'RRHH'].includes(dec) ? ':rotating_light: ' : '';
  const mail = p.sessionId.replace(/^(.).*(@.*)$/, '$1***$2');
  return `${alerta}*${dec}* · ${p.nombre} (${mail})\nAsunto: ${p.asunto}\nBorrador listo en Gmail para revisión.`;
})() }}
